begin;
create or replace function public.notification_category_enabled(target_profile uuid, category text)
returns boolean language plpgsql stable security definer set search_path=public as $$
declare pref public.notification_preferences%rowtype; begin select * into pref from public.notification_preferences where profile_id=target_profile; if not found then return true; end if; return case category when 'games' then pref.games when 'rep' then pref.rep when 'missions' then pref.missions when 'fantasy' then pref.fantasy when 'runs' then pref.runs when 'media' then pref.media when 'lab' then pref.lab when 'pickem' then pref.pickem when 'messages' then pref.messages when 'comments' then pref.comments when 'reactions' then pref.reactions when 'announcements' then pref.announcements else true end; end $$;
create or replace function public.reward_published_highlight() returns trigger language plpgsql security definer set search_path=public as $$ declare already boolean; begin if new.status<>'published' or (tg_op='UPDATE' and old.status='published') or new.uploaded_by is null then return new; end if; select exists(select 1 from public.xp_transactions where profile_id=new.uploaded_by and source_type='highlight_published' and source_id=new.id) into already; if not already then insert into public.user_levels(profile_id) values(new.uploaded_by) on conflict do nothing; insert into public.xp_transactions(profile_id,amount,reason,source_type,source_id,rep_dimension) values(new.uploaded_by,25,'published_highlight','highlight_published',new.id,'creator'); update public.user_levels set xp=xp+25,level=public.level_for_xp(xp+25),updated_at=now() where profile_id=new.uploaded_by; if public.notification_category_enabled(new.uploaded_by,'media') then insert into public.notifications(recipient_id,type,title,body,link) values(new.uploaded_by,'highlight_published','Highlight approved','Your highlight “'||new.title||'” is live on RCL TV. +25 Creator REP.','/media'); end if; end if; return new; end $$;
drop trigger if exists reward_published_highlight_after_write on public.player_highlights; create trigger reward_published_highlight_after_write after insert or update of status on public.player_highlights for each row execute function public.reward_published_highlight();
create or replace function public.reward_scouting_report() returns trigger language plpgsql security definer set search_path=public as $$ declare today_count integer; begin select count(*) into today_count from public.xp_transactions where profile_id=new.author_profile_id and source_type='scouting_report' and created_at>=date_trunc('day',now()); if today_count<3 then insert into public.user_levels(profile_id) values(new.author_profile_id) on conflict do nothing; insert into public.xp_transactions(profile_id,amount,reason,source_type,source_id,rep_dimension) values(new.author_profile_id,15,'scouting_report','scouting_report',new.id,'coach'); update public.user_levels set xp=xp+15,level=public.level_for_xp(xp+15),updated_at=now() where profile_id=new.author_profile_id; if public.notification_category_enabled(new.author_profile_id,'rep') then insert into public.notifications(recipient_id,type,title,body,link) values(new.author_profile_id,'coach_rep','Coach REP earned','Private scouting work added +15 Coach REP.','/coaches/scouting'); end if; end if; return new; end $$;
drop trigger if exists reward_scouting_report_after_insert on public.scouting_reports; create trigger reward_scouting_report_after_insert after insert on public.scouting_reports for each row execute function public.reward_scouting_report();
create or replace function public.notify_mission_completion() returns trigger language plpgsql security definer set search_path=public as $$ declare mission_title text; reward integer; begin if new.completed_at is null or (tg_op='UPDATE' and old.completed_at is not null) then return new; end if; if not public.notification_category_enabled(new.profile_id,'missions') then return new; end if; select title,reward_xp into mission_title,reward from public.weekly_missions where id=new.mission_id; insert into public.notifications(recipient_id,type,title,body,link) values(new.profile_id,'mission_complete','Mission complete',coalesce(mission_title,'Weekly mission')||' is complete. Claim +'||coalesce(reward,0)||' REP.','/missions'); return new; end $$;
drop trigger if exists notify_mission_completion_after_write on public.mission_progress; create trigger notify_mission_completion_after_write after insert or update of completed_at on public.mission_progress for each row execute function public.notify_mission_completion();
create or replace function public.notify_special_player_card() returns trigger language plpgsql security definer set search_path=public as $$ declare owner uuid; player_name text; begin select profile_id,trim(first_name||' '||last_name) into owner,player_name from public.players where id=new.player_id; if owner is null or not public.notification_category_enabled(owner,'games') then return new; end if; insert into public.notifications(recipient_id,type,title,body,link) values(owner,'player_card','New RCL player card',coalesce(new.title,'Special edition')||' unlocked for '||coalesce(player_name,'your player profile')||'.','/players/'||new.player_id||'/passport'); return new; end $$;
drop trigger if exists notify_special_player_card_after_insert on public.player_cards; create trigger notify_special_player_card_after_insert after insert on public.player_cards for each row execute function public.notify_special_player_card();
create or replace function public.score_pickem_game() returns trigger language plpgsql security definer set search_path=public as $$ declare pick_row record; winning_team uuid; earned integer; already_awarded boolean; begin if new.status::text<>'completed' or old.status::text='completed' then return new; end if; if new.home_score=new.away_score then return new; end if; winning_team:=case when new.home_score>new.away_score then new.home_team_id else new.away_team_id end; for pick_row in select * from public.pickem_picks where game_id=new.id for update loop earned:=0; if pick_row.selected_team_id=winning_team then earned:=earned+20; end if; if pick_row.predicted_home_score is not null and pick_row.predicted_away_score is not null then if (pick_row.predicted_home_score-pick_row.predicted_away_score)=(new.home_score-new.away_score) then earned:=earned+10; end if; if pick_row.predicted_home_score=new.home_score and pick_row.predicted_away_score=new.away_score then earned:=earned+15; end if; end if; update public.pickem_picks set points_earned=earned,scored_at=now(),updated_at=now() where id=pick_row.id; if earned>0 then select exists(select 1 from public.xp_transactions where profile_id=pick_row.profile_id and source_type='pickem_score' and source_id=pick_row.id) into already_awarded; if not already_awarded then insert into public.user_levels(profile_id) values(pick_row.profile_id) on conflict do nothing; insert into public.xp_transactions(profile_id,amount,reason,source_type,source_id,rep_dimension) values(pick_row.profile_id,earned,'pickem_result','pickem_score',pick_row.id,'community'); update public.user_levels set xp=xp+earned,level=public.level_for_xp(xp+earned),updated_at=now() where profile_id=pick_row.profile_id; if public.notification_category_enabled(pick_row.profile_id,'pickem') then insert into public.notifications(recipient_id,type,title,body,link) values(pick_row.profile_id,'pickem_result','Pick’em result','+'||earned||' REP from your '||coalesce((select t.name from public.teams t where t.id=pick_row.selected_team_id),'RCL')||' pick.','/pickem'); end if; end if; end if; end loop; return new; end $$;
revoke execute on function public.notification_category_enabled(uuid,text) from public,anon,authenticated; revoke execute on function public.reward_published_highlight() from public,anon,authenticated; revoke execute on function public.reward_scouting_report() from public,anon,authenticated; revoke execute on function public.notify_mission_completion() from public,anon,authenticated; revoke execute on function public.notify_special_player_card() from public,anon,authenticated;
commit;
